import{_ as l,C as e,o,c as r,j as a,a as p,E as s,a3 as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"坐忘论·得道","description":"坐忘论终章精读：道力由心及形，形神合同，炼形入微，与道冥一；并含七篇总纲。","frontmatter":{"title":"坐忘论·得道","description":"坐忘论终章精读：道力由心及形，形神合同，炼形入微，与道冥一；并含七篇总纲。","category":"guide","aliases":["坐忘论得道","得道七","坐忘论精读之八"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-07.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-07.md","lastUpdated":1789714390000}'),c={name:"daoism/daoist-classics/zuowang-lun/chapter-07.md"};function g(b,t,u,m,x,v){const i=e("DaoReadingPrelude"),n=e("DaoTextReading"),d=e("DaoKeywordCards");return o(),r("div",null,[t[0]||(t[0]=a("h1",{id:"坐忘论·得道",tabindex:"-1"},[p("坐忘论·得道 "),a("a",{class:"header-anchor",href:"#坐忘论·得道","aria-label":'Permalink to "坐忘论·得道"'},"​")],-1)),s(i,{title:"形随道通，与神合一",summary:"七篇终章。前六篇都在逐层消除人与道之间的阻隔，本篇进一步追问：道力能否由心及形，使整个生命——不只是意识，也包括形体——发生转化？司马承祯的回答是肯定的，并把得道分为「及心」与「被形」两个深浅层次。",points:[{label:"说道体",text:"灵而有性，虚而无象；不知所以然而然，通生无匮谓之道。"},{label:"说深浅",text:"深则兼被于形，浅则唯及于心——差别在道力，不在言说。"},{label:"说归宿",text:"含光藏辉，凝神宝气，学道无心，神与道合，谓之得道。"}],hint:"本篇含道教成仙论内容（长生、炼形、神人真身）。可作宗教层面理解，不必全部折算为现代心理学结论；其中蹈水火、六根洞达等描述也不可作为现实模仿或追求的目标。"}),t[1]||(t[1]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[p("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),t[2]||(t[2]=a("p",null,[a("strong",null,"一、道的性质与得道的可能")],-1)),s(n,{paragraphs:["夫道者，神异之物，灵而有性，虚而无象，随迎不测，影响莫求，不知所以然而然，通生无匮谓之道。","至圣得之于古，妙法传之于今，循名究理，全然有实。","上士纯信，克己勤行，虚心谷神，唯道来集。"]}),t[3]||(t[3]=a("p",null,[a("strong",null,"二、道力改变形神，成就神人")],-1)),s(n,{paragraphs:["道有深力，徐易形神，形随道通，与神合一，谓之神人。","神性虚融，体无变灭，形与道同，故无生死。隐则形同于神，显则神同于气，所以蹈水火而无害，对日月而无影，存亡在己，出入无间，身为滓质，犹至虚妙，况其灵智益深益远乎？","生神经云：身神并一，则为真身。"]}),t[4]||(t[4]=a("p",null,[a("strong",null,"三、道力有深浅：及心与被形")],-1)),s(n,{paragraphs:["又西升经云：形神合同，故能长久。","然虚无之道，力有浅深，深则兼被于形，浅则唯及于心。被形者，神人也。及心者，但得慧觉，而身不免谢。何耶？","慧是心用，用多则心劳。初得少慧，悦而多辩，神气漏泄，无灵润身光，遂致早终，道故难备。经云尸解，此之谓也。"]}),t[5]||(t[5]=a("p",null,[a("strong",null,"四、含光藏辉，凝神宝气，才叫得道")],-1)),s(n,{paragraphs:["是故大人含光藏辉，以期全备，凝神宝气，学道无心，神与道合，谓之得道。","经云：同于道者，道亦得之。又云：古之所以贵此道者何？不日求以得，有罪以免邪？","山有玉，草木以之不雕。人怀道，形骸以之永固。资薰日久，变质同神，链形入微，与道冥一。"]}),t[6]||(t[6]=a("p",null,[a("strong",null,"五、一身与万法互摄，真应无方")],-1)),s(n,{paragraphs:["散一身为万法，混万法为一身，智照无边，形超靡极，总色空而为用，含造化以成功，真应无方，其惟道德。","西升经云：与天同心而无知，与道同身而无体，然后天道盛矣。谓证得其极者也。又云：神不出身，与道同久。"]}),t[7]||(t[7]=a("p",null,[a("strong",null,"六、六根皆与道同，以及对「唯舍形论」的批评")],-1)),s(n,{paragraphs:["且身与道同，则无时而不存；心与道同，则无法而不通；耳与道同，则无声而不闻；眼与道同，则无色而不见。六根洞达，良由于此。","近代常流，识不及远，唯闻舍形之道，未达即身之妙，无惭己短，有效人非。","其犹夏虫不信冰霜，醯鸡断无天地。其愚不可及，何可诲焉。"]}),t[8]||(t[8]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(d,{items:[{term:"神异之物",pinyin:["shén","yì","zhī","wù"],meaning:"此处「物」不宜按普通有形物质理解，因紧接便说「虚而无象」。近于「神妙不可测的真实」：不能由感官直接限定，却贯通生成万物。"},{term:"灵而有性",pinyin:["líng","ér","yǒu","xìng"],meaning:"道灵妙而具有真实本性。强调「有性」，是防止把虚无之道误解成什么都没有——道虚不等于不存在，道无象不等于无作用。"},{term:"虚而无象",pinyin:["xū","ér","wú","xiàng"],meaning:"道虚通而没有固定形象：不被一个形体限定，不为任何一物独占，不能当作特殊对象抓取。"},{term:"随迎不测",pinyin:["suí","yíng","bù","cè"],meaning:"向前往迎、从后追随都无法用普通方式测定。近《道德经》「迎之不见其首，随之不见其后」：道不是可被前后追踪的空间对象。"},{term:"影响莫求",pinyin:["yǐng","xiǎng","mò","qiú"],meaning:"影随形、响应声，道的作用虽如此，却不能作为独立对象强行求得。道不能用世俗占有外物的方式求取。"},{term:"通生无匮",pinyin:["tōng","shēng","wú","kuì"],meaning:"贯通、生成和养育万物，其作用无穷无尽。道体虚而无象，道用则通生无匮。"},{term:"虚心谷神",pinyin:["xū","xīn","gǔ","shén"],meaning:"虚心，心不被爱恶名利和多知填满；谷神语出《道德经》第六章「谷神不死」，谓心神如空谷——虚而能受，空而能应，不自满不固执。"},{term:"徐易形神",pinyin:["xú","yì","xíng","shén"],meaning:"徐，渐渐；易，改变。道力经长期薰习而逐渐改变形体与精神。对应前篇的「日损有为」「久久调熟」「资薰日久」。"},{term:"形随道通",pinyin:["xíng","suí","dào","tōng"],meaning:"形体随道力薰习而变得通达，不再保持普通滞碍之质。后文称之为「变质同神，炼形入微」——不是简单保养身体，而是存在方式的根本转变。"},{term:"神人",pinyin:["shén","rén"],meaning:"《庄子·逍遥游》中的理想人格（「神人无功」），道教中又具形神超化、具足神通之意。本篇所说神人兼有两层：心性上无己无名无执，形神上与道合一。"},{term:"虚融",pinyin:["xū","róng"],meaning:"虚，无固定实体可执；融，无碍贯通不与道隔。神之所以能与道相合，正因二者都具有虚通性质。"},{term:"尸解",pinyin:["shī","jiě"],meaning:"道教仙学概念，指修道者死后遗下形骸衣冠等物、以某种方式脱离肉身。不同道教时期评价不一；本篇把它归入「道力及心、身仍不免谢」的未全层次。"},{term:"含光藏辉",pinyin:["hán","guāng","cáng","huī"],meaning:"把内在智慧光明含藏起来，不急于向外炫耀。非故意装作无知，而是不用所得建立身份、不因有慧便到处辩论。近《道德经》「和其光，同其尘」。"},{term:"凝神宝气",pinyin:["níng","shén","bǎo","qì"],meaning:"使精神凝聚，珍惜并保养生命之气。「宝」作动词，以之为宝而爱护。非把气想象成可任意操纵的物质，而是减少精神耗散、使形神相养。"},{term:"学道无心",pinyin:["xué","dào","wú","xīn"],meaning:"修道而不带强烈的占有心、功利心和自我意识：不想靠修道获得名声，不想证明有境界，不想把大道当作自己的所有物。"},{term:"资薰日久",pinyin:["zī","xūn","rì","jiǔ"],meaning:"依靠大道长期薰习浸润，如香气久熏衣物。一次静坐不足以改易形神，须长期定慧相养、神气不漏，才会发生深层变化。"},{term:"变质同神",pinyin:["biàn","zhì","tóng","shén"],meaning:"身体原本粗重的形质逐渐变化，变得与神同样虚妙。这是「道力兼被于形」的结果，故形神才能不相分离。"},{term:"炼形入微",pinyin:["liàn","xíng","rù","wēi"],meaning:"通过道力与神气的长期薰炼，使形体进入精微虚化的状态。粗形→气化→神化→与道冥一。本篇未详论吐纳外丹，而把炼形之本放在虚心、定慧、含光、凝神、宝气。"},{term:"冥一",pinyin:["míng","yī"],meaning:"不是外在拼合，不是概念宣布，也不是「我与道合一」的自我感觉，而是界限与阻碍自然消失——心、神、形皆不再与道隔。"},{term:"总色空而为用",pinyin:["zǒng","sè","kōng","ér","wéi","yòng"],meaning:"统摄有形（色）与无自性（空）而能自在运用，不滞于任何一端。带明显佛教色空语言影响，被纳入道教形神仙化：色不定色故形可炼化，空不滞空故神可显用。"},{term:"真应无方",pinyin:["zhēn","yìng","wú","fāng"],meaning:"真实的感应与作用没有固定形式，能随缘而应：隐显无定、动静不滞、有无相通、应后不留。与【收心】「神用无方」首尾呼应。"},{term:"无知无体",pinyin:["wú","zhī","wú","tǐ"],meaning:"《西升经》「与天同心而无知，与道同身而无体」。无知所破是人为智巧与自以为知（非无觉）；无体所破是固定粗重形体之执（非不存在）。"},{term:"六根洞达",pinyin:["liù","gēn","dòng","dá"],meaning:"六根（眼耳鼻舌身意，佛教术语）完全通达，不再受普通障碍限制。本篇把它解释为整个形神与道相同的结果，而非单独训练感官异能所得。"},{term:"即身之妙",pinyin:["jí","shēn","zhī","miào"],meaning:"不必先舍弃身体，此现有形身本身也可以经过道化而成真。非「离身之外另求真身」，而是此身由粗入微、由形合神，转为真身。"},{term:"醯鸡",pinyin:["xī","jī"],meaning:"醋瓮中滋生的小虫，生活在狭小容器中而视野极为有限。喻因见闻狭隘便武断否定广大天地者。"}]}),t[9]||(t[9]=h("",197))])}const q=l(c,[["render",g]]);export{y as __pageData,q as default};
